// block-hadamard-fused-norm.wgsl.jinja — root template (upstream/engine.pretty.js lines 22277-22332)
function wgslTemplateBlockHadamardFusedNorm(v: JinjaVars): string {
  let out = "";
  out += wgslIncludeTreeFoldInplace(v);
  out += `
${jinja.out(jinja.get(jinja.get(v.env, "wgsl"), "resourceDeclarations"))}

const WIDTH: u32 = ${jinja.out(v.width)}u;
const WIDTH_VEC4: u32 = ${jinja.out(v.widthVec4)}u;
const BLOCK: u32 = ${jinja.out(v.blockSize)}u;
const RMS_EPS: f32 = ${jinja.out(v.rmsEps)};
const W_NORM: u32 = ${jinja.out(v.normOffset)}u;
const WORKGROUP_SIZE: u32 = 256u;

var<workgroup> partials: array<f32, 256>;
var<workgroup> values: array<f32, ${jinja.out(v.blockSize)}>;

fn sum4(value: vec4<f32>) -> f32 {
  return value.x + value.y + value.z + value.w;
}

@compute @workgroup_size(256)
fn main(@builtin(workgroup_id) wg: vec3<u32>, @builtin(local_invocation_index) lid: u32) {
  let row = wg.y * WIDTH;
  var sum = 0.0;
  for (var quad = lid; quad < WIDTH_VEC4; quad = quad + WORKGROUP_SIZE) {
    let e = row + quad * 4u;
    let value = vec4<f32>(f32(x[e]), f32(x[e + 1u]), f32(x[e + 2u]), f32(x[e + 3u]));
    sum = sum + sum4(value * value);
  }
  partials[lid] = sum;
  workgroupBarrier();

${jinja.out(jinja.call(v, v.wgsl_tree_fold, [["partials"]]))}

  let scale = inverseSqrt(partials[0] / f32(WIDTH) + RMS_EPS);
  let blockBase = wg.x * BLOCK;
  for (var e = lid; e < BLOCK; e = e + WORKGROUP_SIZE) {
    let scaled = f32(x[row + blockBase + e]) * scale * f32(normWeights[W_NORM + blockBase + e]);
`;
  if (jinja.bool(v.teeNormed)) {
    out += `    normed[row + blockBase + e] = scaled;
`;
  }
  out += `    values[e] = scaled * signs[blockBase + e];
  }
  workgroupBarrier();
  for (var span = 1u; span < BLOCK; span *= 2u) {
    for (var pair = lid; pair < ${jinja.out(jinja.filterInt(jinja.div(v.blockSize, 2)))}u; pair += WORKGROUP_SIZE) {
      let lo = (pair / span) * (2u * span) + pair % span;
      let a = values[lo];
      let c = values[lo + span];
      values[lo] = a + c;
      values[lo + span] = a - c;
    }
    workgroupBarrier();
  }
  for (var e = lid; e < BLOCK; e = e + WORKGROUP_SIZE) {
    y[row + blockBase + e] = ${jinja.out(v.yScalar)}(values[e] * inverseSqrt(f32(BLOCK)));
  }
}`;
  return out;
}

