// ops/_shared/sigmoid-safe.wgsl.jinja — include (upstream/engine.pretty.js lines 10999-11006); shares the including template's scope
function wgslIncludeSigmoidSafe(v: JinjaVars): string {
  let out = "";
  out += `fn sigmoid_safe(x: f32) -> f32 {
  if (x >= 0.0) {
    let z = exp(-x);
    return 1.0 / (1.0 + z);
  }
  let z = exp(x);
  return z / (1.0 + z);
}`;
  return out;
}

