function wgslTemplatePrefillMatmul(v: JinjaVars): string {
  let out = "";
  if (jinja.bool(v.usesF16)) {
    out += `enable f16;
`;
  }
  out += `${jinja.out(jinja.get(jinja.get(v.env, "wgsl"), "resourceDeclarations"))}

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {

  let g = gid.x + gid.y * ${jinja.out(v.DISPATCH_FOLD_WIDTH)}u * 64u;
  let total = params.m * params.out_features;
  if (g >= total) {
    return;
  }
  let row = g / params.out_features;
  let col = g % params.out_features;
  let a_base = row * params.in_features;
  let w_base = params.weight_offset + col * params.in_features;
  var acc = 0.0;
  for (var k = 0u; k < params.in_features; k = k + 1u) {
    acc = acc + f32(a[a_base + k]) * f32(weights[w_base + k]);
  }
  y[g] = ${jinja.out(v.yScalar)}(acc);
}`;
  return out;
}

