    for (let k = 0; k < 5; k++) {
      lines.push(`  ${k === 0 ? "var " : ""}ph = h * 3u; r = fma(xh${k}.x, ${f("(ph >> 8u) & 0xffu")}, r); r = fma(xh${k}.y, ${f("ph >> 24u")}, r);${k < 4 ? " h = ph & 0x00ff00ffu;" : ""}`);
    }
