/** The degeneracy verdict: a tower whose every output is one value (or not finite) computed nothing,
 *  however fast it ran. Returns the printable reason, or null when the output is alive. */
export function visionDegeneracyVerdict(embeds: ArrayLike<number>): string | null {
  if (embeds.length === 0) return "the vision stage produced no output";
  let lo = Infinity;
  let hi = -Infinity;
  let bad = 0;
  for (let i = 0; i < embeds.length; i++) {
    const x = embeds[i];
    // NaN compares false against everything, so min/max tracking alone would miss it: count explicitly
    if (!Number.isFinite(x)) { bad++; continue; }
    if (x < lo) lo = x;
    if (x > hi) hi = x;
  }
  if (bad > 0) return `the vision stage produced ${bad} non-finite value(s) out of ${embeds.length}`;
  if (hi - lo < 1e-9) return `every output of the vision stage is the same value (min ${lo}, max ${hi})`;
  return null;
}

/**
 * Decode an ImageBitmap / <img> / Blob to interleaved u8 RGB at its own size — or, when `shrink(w, h)` returns a smaller
 * size, at that size (P2.5: `createImageBitmap(..., { resizeWidth, resizeHeight, resizeQuality: "high" })` shrinks a
 * 48 MP photo to ~2× the tower's target before the CPU sees a single pixel; the exact Pillow bicubic then does the last
 * step, so the numerics of a normal-sized image are unchanged). Transparent pixels are composited on WHITE (P2.3: a
 * canvas is premultiplied, so alpha 0 used to read back as black and dark text on a transparent PNG vanished).
 */
export async function visionImageToRgb(image: ImageBitmap | HTMLImageElement | Blob, opts: { shrink?: (w: number, h: number) => { w: number; h: number } | null } = {}): Promise<{ rgb: Uint8Array; w: number; h: number; natural: { w: number; h: number } }> {
  let bmp: ImageBitmap;
  let own = false;
  if (typeof ImageBitmap !== "undefined" && image instanceof ImageBitmap) {
    bmp = image;
  } else if (typeof Blob !== "undefined" && image instanceof Blob) {
    bmp = await createImageBitmap(image);
    own = true;
  } else {
    const el = image as HTMLImageElement;
    if (!el.complete || el.naturalWidth === 0) await el.decode();
    bmp = await createImageBitmap(el);
    own = true;
  }
  try {
    const natural = { w: bmp.width, h: bmp.height };
    if (!(natural.w > 0 && natural.h > 0)) throw new Error(`vision: image decodes to ${natural.w}x${natural.h}`);
    const want = opts.shrink?.(natural.w, natural.h);
    if (want && want.w > 0 && want.h > 0 && (want.w < natural.w || want.h < natural.h)) {
      const small = await createImageBitmap(bmp, { resizeWidth: Math.max(1, Math.round(want.w)), resizeHeight: Math.max(1, Math.round(want.h)), resizeQuality: "high" });
      if (own) bmp.close();
      bmp = small;
      own = true;
    }
    const w = bmp.width, h = bmp.height;
    let ctx: OffscreenCanvasRenderingContext2D | CanvasRenderingContext2D | null;
    if (typeof OffscreenCanvas !== "undefined") {
      ctx = new OffscreenCanvas(w, h).getContext("2d", { willReadFrequently: true });
    } else {
      const c = document.createElement("canvas");
      c.width = w;
      c.height = h;
      ctx = c.getContext("2d", { willReadFrequently: true });
    }
    if (!ctx) throw new Error("vision: 2d canvas context unavailable");
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, w, h);
    ctx.drawImage(bmp, 0, 0);
    const data = ctx.getImageData(0, 0, w, h).data;
    const rgb = new Uint8Array(w * h * 3);
    for (let i = 0, j = 0, k = 0; i < w * h; i++, j += 4, k += 3) {
      rgb[k] = data[j];
      rgb[k + 1] = data[j + 1];
      rgb[k + 2] = data[j + 2];
    }
    return { rgb, w, h, natural };
  } finally {
    if (own) bmp.close();
  }
}

/** P2.5: the size to pre-shrink a w × h source to before the CPU resample — about 2× the target on both axes (null = keep) */
export function visionPreShrinkSize(w: number, h: number, target: { w: number; h: number }): { w: number; h: number } | null {
  const f = Math.max((2 * target.w) / w, (2 * target.h) / h);
  if (!(f < 1)) return null;
  return { w: Math.max(target.w, Math.round(w * f)), h: Math.max(target.h, Math.round(h * f)) };
}

// ── P9.2 image-embedding guard (§12.0d) ──

/**
 * The healthy per-token RMS range of the tower's output rows (projectionDim f32 each), ≥ 10× margin on each side of what
 * healthy encodes measured. Measured on the Vega II (Radeon Pro Vega II, Chromium/Vulkan, 2026-09-23, Q8_0 mmproj,
 * tests/bench.html: 4 encodes per image, every row): the int8 tier on 10 images — the scene / sign3 / transparent-text
 * fixtures, a 1.9 MB PNG graphic, two NASA photos, a plasma fractal, solid black and solid white (1024–2304 tokens each)
 * — 0.1905 (sign3) .. 3.4226 (moons photo); tiled3 on scene / earth / black 0.2093..2.6559, legacy on scene / earth
 * 0.2093..2.6559. Healthy range 0.1905..3.4226 → bounds 0.015 (12.7× below) .. 50 (14.6× above).
 */
export const VISION_GUARD_RMS_BOUNDS: Readonly<TextGuardBounds> = Object.freeze({ min: 0.015, max: 50 });
/** WGSL of the guard reduction: one workgroup per image token → [sum of squares of the finite values, non-finite count] */
export function visionGuardWgsl(dim: number): string {
  return /* wgsl */ `
@group(0) @binding(0) var<storage, read> x: array<f32>;
@group(0) @binding(1) var<storage, read_write> stats: array<vec2<f32>>;
const DIM: u32 = ${dim}u;
const WG: u32 = 256u;
var<workgroup> wss: array<f32, WG>;
var<workgroup> wbad: array<u32, WG>;
@compute @workgroup_size(256)
fn main(@builtin(workgroup_id) wg: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
  let row = wg.x;
  var ss: f32 = 0.0;
  var bad: u32 = 0u;
  for (var i: u32 = lid.x; i < DIM; i = i + WG) {
    let v = x[row * DIM + i];
    // exponent all ones = ±inf or NaN (bit test: fast-math compilers may fold isnan away)
    if ((bitcast<u32>(v) & 0x7f800000u) == 0x7f800000u) {
      bad = bad + 1u;
    } else {
      ss = fma(v, v, ss);
    }
  }
  wss[lid.x] = ss;
  wbad[lid.x] = bad;
  workgroupBarrier();
  for (var s: u32 = WG / 2u; s > 0u; s = s >> 1u) {
    if (lid.x < s) {
      wss[lid.x] = wss[lid.x] + wss[lid.x + s];
      wbad[lid.x] = wbad[lid.x] + wbad[lid.x + s];
    }
    workgroupBarrier();
  }
  if (lid.x == 0u) {
    stats[row] = vec2<f32>(wss[0], f32(wbad[0]));
  }
}
`;
}
/**
 * The guard's verdict on one encode's stats ([sum of squares, non-finite count] per token, visionGuardWgsl) — null when
 * every token is finite with its RMS inside `bounds` (pure). Also returns the RMS range it saw.
 */
export function visionGuardVerdict(stats: ArrayLike<number>, nTokens: number, dim: number, bounds: TextGuardBounds = VISION_GUARD_RMS_BOUNDS): { reason: string | null; rmsMin: number; rmsMax: number } {
  let rmsMin = Infinity;
  let rmsMax = 0;
  let bad = 0;
  let badTokens = 0;
  let low = 0;
  let high = 0;
  let first = -1;
  for (let t = 0; t < nTokens; ++t) {
    const nf = stats[2 * t + 1]!;
    const rms = Math.sqrt(stats[2 * t]! / dim);
    if (!(nf === 0)) {
      bad += Number.isFinite(nf) ? nf : dim;
      badTokens++;
      if (first < 0) first = t;
      continue;
    }
    if (!(rms >= bounds.min)) {
      low++;
      if (first < 0) first = t;
    } else if (!(rms <= bounds.max)) {
      high++;
      if (first < 0) first = t;
    }
    if (rms < rmsMin) rmsMin = rms;
    if (rms > rmsMax) rmsMax = rms;
  }
  const n = (x: number): string => (Number.isFinite(x) ? String(Number(x.toPrecision(4))) : String(x));
  let reason: string | null = null;
  if (badTokens > 0) reason = `${bad} non-finite value(s) in ${badTokens} of ${nTokens} image tokens (first: token ${first})`;
  else if (low + high > 0) reason = `${low + high} of ${nTokens} image tokens have an RMS outside the healthy range [${bounds.min}, ${bounds.max}] (${low} below, ${high} above; range seen ${n(rmsMin)} … ${n(rmsMax)}; first: token ${first})`;
  return { reason, rmsMin, rmsMax };
}

class VisionTowerImpl implements VisionTower {
  readonly config: VisionConfig;
  readonly maxImageEdge: number;
  readonly maxImageTokensRequested: number;
  readonly residentBytes: number;
  readonly weightsFormat: VisionWeightsFormat;
  private readonly g: VisionGpu;
  private readonly w8: VisionGpuWeights;
  private queue: Promise<unknown> = Promise.resolve();
  private disposed = false;
  private set: VisionKernelSet;
  /** the lower rungs a failed load check may still drop to, best first */
  private readonly rungs: VisionKernelSet[];
  /** "auto" mode: a tiled forward that fails switches this tower to the reference kernels for good */
  private readonly mayFallBack: boolean;
  private readonly request: VisionKernelRequest;
  private readonly onDiagnostic?: (d: GpuDiagnostic) => void;
  readonly weightsId: string;
  /** every rung considered so far, best first (unsupported, failed compile / check, runtime switches, the one in use) */
  readonly ladder: VisionLadderStep[];
  check: VisionCheck | null = null;
  // ── P9.2 image-embedding guard ──
  guard: VisionGuardInfo | null = null;
  onGuard?: (g: VisionGuardInfo) => void;
  private readonly guardAcc: VisionGuardStats = { encodes: 0, tokens: 0, rmsMin: Infinity, rmsMax: 0, lastMs: 0 };
  private guardPipeline: Promise<GPUComputePipeline | null> | null = null;
  /** "image": the first check reads corrupted stats (once); "image-all": every check does */
  guardFault: "image" | "image-all" | null = null;
  private guardFaultFired = false;

  constructor(config: VisionConfig, g: VisionGpu, w8: VisionGpuWeights, limits: { maxImageEdge: number; maxImageTokensRequested: number }, kernels: VisionKernelSet, rungs: VisionKernelSet[], request: VisionKernelRequest, ladder: VisionLadderStep[], weightsId: string, onDiagnostic?: (d: GpuDiagnostic) => void) {
    this.config = config;
    this.g = g;
    this.w8 = w8;
    this.maxImageEdge = limits.maxImageEdge;
    this.maxImageTokensRequested = limits.maxImageTokensRequested;
    this.residentBytes = w8.residentBytes;
    this.weightsFormat = w8.format;
    this.set = kernels;
    this.rungs = rungs;
    this.request = request;
    this.mayFallBack = request === "auto";
    this.ladder = ladder;
    this.weightsId = weightsId;
    this.onDiagnostic = onDiagnostic;
  }

  get kernels(): VisionKernelSet {
    return this.set;
  }

  /** what `set` compiles for this tower's weight packings */
  names(set: VisionKernelSet): VisionKernelName[] {
    return visionKernelNamesFor(set, this.w8.kinds);
  }

  /** the token budget in force: the request, capped by what the current set's buffers may hold on this device */
  get maxImageTokens(): number {
    return Math.min(this.maxImageTokensRequested, this.deviceTokenCap(this.set));
  }

  deviceTokenCap(set: VisionKernelSet): number {
    return Math.min(visionMaxTokensForKernels(this.g.limits, this.config, set), Math.floor(this.config.maxPixels / (this.config.alignSize * this.config.alignSize)));
  }

  get tier(): VisionTierInfo {
    return { kernels: this.set, requested: this.request, ladder: this.ladder.map((s) => ({ ...s })) };
  }

  /** Load time: drop to the next rung that compiles (the caller re-runs the check). False when none is left. */
  async nextRung(reason: string): Promise<boolean> {
    if (this.g.lostReason || this.disposed) return false;
    while (this.rungs.length > 0) {
      const next = this.rungs.shift() as VisionKernelSet;
      try {
        await this.g.compileAll(this.names(next));
      } catch (e) {
        if (this.g.lostReason) return false;
        this.ladder.push({ kernels: next, ok: false, stage: "compile", reason: visionErrText(e) });
        continue;
      }
      this.onDiagnostic?.({ stage: "build", label: "vision", message: `vision: ${this.set} kernels rejected (${reason.split("\n")[0]}); trying ${next}` });
      this.set = next;
      return true;
    }
    return false;
  }

  /** Runtime: switch to the reference kernels (compiling them on first use). False when this tower may not or need not. */
  async fallBack(reason: string, stage: GpuDiagnostic["stage"] = "execute"): Promise<boolean> {
    if (!this.mayFallBack || this.set === "legacy" || this.g.lostReason || this.disposed) return false;
    this.onDiagnostic?.({ stage, label: "vision", message: `vision: switching from the ${this.set} kernels to the reference kernels — ${reason}` });
    await this.g.compileAll(this.names("legacy"));
    this.ladder.push({ kernels: this.set, ok: false, stage: "execute", reason });
    this.set = "legacy";
    this.ladder.push({ kernels: "legacy", ok: true, stage: "execute", reason: "runtime fallback" });
    return true;
  }

  /** errors worth a second try with the other kernels: not an abort, not out-of-memory, not a lost device */
  private static retryable(e: unknown): boolean {
    if ((e as { name?: string })?.name === "AbortError") return false;
    return !/out of memory|device lost/i.test(visionErrText(e));
  }

  /** encodes run one at a time (they share the pipelines and the device queue) */
  private serial<T>(fn: () => Promise<T>): Promise<T> {
    const next = this.queue.then(fn, fn);
    this.queue = next.catch(() => {});
    return next;
  }

  /** the limits one image is preprocessed under */
  private get imageLimits(): VisionImageLimits {
    return { maxEdge: this.maxImageEdge, maxTokens: this.maxImageTokens };
  }

  plan(w: number, h: number): { w: number; h: number; tokens: number } {
    const t = visionTargetSize(Math.max(1, Math.round(w)), Math.max(1, Math.round(h)), this.config, this.imageLimits);
    return { w: t.w, h: t.h, tokens: visionTokenGeometry(t.w, t.h, this.config).nTokens };
  }

  encode(image: ImageBitmap | HTMLImageElement | Blob, opts: { signal?: AbortSignal } = {}): Promise<VisionEncoding> {
    return this.serial(async () => {
      if (this.disposed) throw new Error("vision: tower disposed");
      if (opts.signal?.aborted) throw new DOMException("vision: encode aborted", "AbortError");
      // the target is decided from the ORIGINAL size (mtmd does the same); a big photo is pre-shrunk to ~2× it (P2.5)
      let target: { w: number; h: number } | undefined;
      const { rgb, w, h } = await visionImageToRgb(image, {
        shrink: (nw, nh) => {
          target = visionTargetSize(nw, nh, this.config, this.imageLimits);
          return visionPreShrinkSize(nw, nh, target);
        },
      });
      return this.encodeRgb(rgb, w, h, opts.signal, target);
    });
  }

  encodeFrames(a: Blob, b: Blob, opts: { signal?: AbortSignal; maxTokens?: number } = {}): Promise<VisionEncoding> {
    return this.serial(async () => {
      if (this.disposed) throw new Error("vision: tower disposed");
      if (opts.signal?.aborted) throw new DOMException("vision: encode aborted", "AbortError");
      const lim: VisionImageLimits = { ...this.imageLimits, ...(opts.maxTokens !== undefined ? { maxTokens: Math.min(opts.maxTokens, this.imageLimits.maxTokens ?? Infinity) } : {}) };
      let target: { w: number; h: number } | undefined;
      const shrink = (nw: number, nh: number): { w: number; h: number } | null => {
        target ??= visionTargetSize(nw, nh, this.config, lim);
        return visionPreShrinkSize(nw, nh, target);
      };
      const fa = await visionImageToRgb(a, { shrink });
      const fb = await visionImageToRgb(b, { shrink });
      const pa = visionPrepareImage(fa.rgb, fa.w, fa.h, this.config, { ...lim, target });
      const pb = visionPrepareImage(fb.rgb, fb.w, fb.h, this.config, { ...lim, target: { w: pa.w, h: pa.h } });
      if (pa.w !== pb.w || pa.h !== pb.h) throw new Error(`vision: video frames differ in size (${pa.w}x${pa.h} vs ${pb.w}x${pb.h})`);
      const geo = visionTokenGeometry(pa.w, pa.h, this.config);
      const embeds = await visionForward(this.g, this.config, this.w8, pa.img, pa.w, pa.h, opts.signal, this.set, undefined, pb.img);
      return { embeds, nTokens: geo.nTokens, grid: geo.grid, patchGrid: geo.patchGrid, preprocessed: { width: pa.w, height: pa.h } };
    });
  }

  /** decoded u8 RGB in — the path smokeTest() and tests use to avoid canvas colour management */
  async encodeRgb(rgb: Uint8Array, w: number, h: number, signal?: AbortSignal, target?: { w: number; h: number }): Promise<VisionEncoding> {
    const prep = visionPrepareImage(rgb, w, h, this.config, { ...this.imageLimits, target });
    const geo = visionTokenGeometry(prep.w, prep.h, this.config);
    let embeds: GPUBuffer;
    try {
      embeds = await visionForward(this.g, this.config, this.w8, prep.img, prep.w, prep.h, signal, this.set);
    } catch (e) {
      const retry = this.set !== "legacy" && VisionTowerImpl.retryable(e)
        && (await this.fallBack(`encoding a ${prep.w}x${prep.h} image failed: ${visionErrText(e)}`));
      if (!retry) throw e;
      embeds = await visionForward(this.g, this.config, this.w8, prep.img, prep.w, prep.h, signal, "legacy");
    }
    // P9.2 (§12.0d): the image-embedding guard — a trip re-encodes on the next tier of the load's ladder, for the session
    for (;;) {
      let reason: string | null;
      try {
        reason = await this.guardCheck(embeds, geo.nTokens);
      } catch (e) {
        embeds.destroy();
        throw e;
      }
      if (reason === null) break;
      embeds.destroy();
      const from = this.set;
      const moved = await this.nextRung(`guard: ${reason}`).catch(() => false);
      this.ladder.push({ kernels: from, ok: false, stage: "guard", reason });
      if (moved) this.ladder.push({ kernels: this.set, ok: true, stage: "guard", reason: `re-encoded after the guard tripped on ${from}` });
      const trips = [...(this.guard?.trips ?? []), { from, reason }];
      this.guard = { tripped: true, from, to: moved ? this.set : null, reason, trips };
      this.onDiagnostic?.({ stage: "execute", label: "vision-guard", kind: "guard", message: `guard: vision ${from} embeddings of a ${prep.w}x${prep.h} image: ${reason}; ${moved ? `re-encoding on ${this.set} (for the rest of the session)` : "no lower tier left"}` });
      try {
        this.onGuard?.(this.guard);
      } catch {
        /* a listener never breaks an encode */
      }
      if (!moved) throw new BonsaiGuardError(`guard: vision — ${from} embeddings: ${reason}; no lower vision tier is left (${this.request} kernels)`, this.guard);
      embeds = await visionForward(this.g, this.config, this.w8, prep.img, prep.w, prep.h, signal, this.set);
    }
    return { embeds, nTokens: geo.nTokens, grid: geo.grid, patchGrid: geo.patchGrid, preprocessed: { width: prep.w, height: prep.h } };
  }

  get guardStats(): Readonly<VisionGuardStats> {
    return { ...this.guardAcc };
  }

  /**
   * P9.2: one reduction over the encode's rows (visionGuardWgsl) and an 8-byte-per-token readback; the reason when the
   * embeddings are non-finite or a token's RMS is outside VISION_GUARD_RMS_BOUNDS, else null. A guard that cannot run
   * (its pipeline failed to build) reports one diagnostic and lets every encode through.
   */
  private async guardCheck(embeds: GPUBuffer, nTokens: number): Promise<string | null> {
    const dim = this.config.projectionDim;
    if (nTokens <= 0 || nTokens > this.g.limits.maxComputeWorkgroupsPerDimension) return null;
    const t0 = performance.now();
    const device = this.g.device;
    this.guardPipeline ??= (async () => {
      try {
        const module = gpuShaderModule(device, visionGuardWgsl(dim), "vision.guard"); // P9.7: through the device's host
        return await gpuComputePipeline(device, { label: "vision.guard", layout: "auto", compute: { module, entryPoint: "main" } });
      } catch (e) {
        this.onDiagnostic?.({ stage: "build", label: "vision-guard", message: `vision: the embedding guard did not build (${visionErrText(e)}); encodes run unguarded` });
        return null;
      }
    })();
    const pipe = await this.guardPipeline;
    if (!pipe) return null;
    this.g.assertAlive("the embedding guard");
    const bytes = nTokens * 8;
    const out = device.createBuffer({ label: "vision.guard.stats", size: bytes, usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC });
    const st = device.createBuffer({ label: "vision.guard.readback", size: bytes, usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ });
    let stats: Float32Array;
    try {
      const bind = device.createBindGroup({ layout: pipe.getBindGroupLayout(0), entries: [{ binding: 0, resource: { buffer: embeds, offset: 0, size: nTokens * dim * 4 } }, { binding: 1, resource: { buffer: out } }] });
      const enc = device.createCommandEncoder({ label: "vision.guard" });
      const pass = enc.beginComputePass({ label: "vision.guard" });
      pass.setPipeline(pipe);
      pass.setBindGroup(0, bind);
      pass.dispatchWorkgroups(nTokens);
      pass.end();
      enc.copyBufferToBuffer(out, 0, st, 0, bytes);
      device.queue.submit([enc.finish()]);
      await st.mapAsync(GPUMapMode.READ);
      stats = new Float32Array(st.getMappedRange().slice(0));
      st.unmap();
    } finally {
      out.destroy();
      st.destroy();
    }
    // BONSAI_GUARD_FAULT=image / image-all: token 0 reads back as blown up (1e8 × its sum of squares)
    if (this.guardFault === "image-all" || (this.guardFault === "image" && !this.guardFaultFired)) {
      this.guardFaultFired = true;
      stats[0] = stats[0]! * 1e8 + 1e8 * dim;
    }
    const v = visionGuardVerdict(stats, nTokens, dim);
    const acc = this.guardAcc;
    acc.encodes++;
    acc.lastMs = Math.round((performance.now() - t0) * 100) / 100;
    if (v.reason === null) {
      acc.tokens += nTokens;
      if (v.rmsMin < acc.rmsMin) acc.rmsMin = v.rmsMin;
      if (v.rmsMax > acc.rmsMax) acc.rmsMax = v.rmsMax;
    }
    return v.reason;
  }

  smokeTest(): Promise<VisionCheck> {
    return this.serial(() => this.checkUnlocked());
  }

  /** the known-answer check (VisionCheck) with the current set: one forward with no retry — the caller decides
   *  whether a failure means falling back. Also stored in `this.check`. */
  private async checkUnlocked(): Promise<VisionCheck> {
    const t0 = performance.now();
    const set = this.set;
    const ref = VISION_SMOKE_REFERENCES.find((r) => r.weightsId === this.weightsId);
    const method: VisionCheck["method"] = ref ? "known" : set !== "legacy" ? "cross" : "degeneracy";
    const base = { kernels: set, method, weightsId: this.weightsId };
    const done = (r: Omit<VisionCheck, "ms" | "kernels" | "method" | "weightsId">): VisionCheck => (this.check = { ...base, ...r, ms: Math.round(performance.now() - t0) });
    try {
      if (this.disposed) throw new Error("vision: tower disposed");
      const { rgb, side } = visionSmokeRgb();
      const prep = visionPrepareImage(rgb, side, side, this.config, this.imageLimits);
      const geo = visionTokenGeometry(prep.w, prep.h, this.config);
      const nBytes = geo.nTokens * this.config.projectionDim * 4;
      const run = async (kernels: VisionKernelSet): Promise<Float32Array> => {
        const buf = await visionForward(this.g, this.config, this.w8, prep.img, prep.w, prep.h, undefined, kernels);
        try {
          return await visionReadbackF32(this.g.device, buf, nBytes);
        } finally {
          buf.destroy();
        }
      };
      const out = await run(set);
      const dead = visionDegeneracyVerdict(out);
      if (dead) {
        const trace = await this.traceUnlocked(set);
        return done({ ok: false, reason: `${dead} — the GPU computed nothing usable — ${trace.summary}`, trace });
      }
      const fingerprint = visionFingerprint(out);
      if (ref) {
        const error = visionFingerprintError(fingerprint, ref.fingerprint);
        const tol = visionKnownAnswerTolerance(set);
        if (error <= tol) return done({ ok: true, fingerprint, error, threshold: tol });
        const trace = await this.traceUnlocked(set);
        const reason = `the ${set} kernels failed the known-answer check: deviation ${error.toExponential(2)} of the reference RMS (limit ${tol}); `
          + `rms ${fingerprint.rms.toPrecision(4)} vs ${ref.fingerprint.rms.toPrecision(4)}, mean ${fingerprint.mean.toPrecision(4)} vs ${ref.fingerprint.mean.toPrecision(4)} — ${trace.summary}`;
        return done({ ok: false, fingerprint, error, threshold: tol, reason, trace });
      }
      if (set !== "legacy") {
        // no stored answer for these weights: the reference kernels on this very device are the yardstick
        await this.g.compileAll(this.names("legacy"));
        const cross = visionCompareOutputs(out, await run("legacy"));
        const lim = visionCrossCheckLimits(set);
        if (cross.cosine >= lim.minCosine && cross.relRms <= lim.maxRelRms) return done({ ok: true, fingerprint, cross });
        const trace = await this.traceUnlocked(set);
        const reason = `the ${set} kernels disagree with the reference kernels on this device: cosine ${cross.cosine.toFixed(6)} (min ${lim.minCosine}), `
          + `relative RMS ${cross.relRms.toExponential(2)} (max ${lim.maxRelRms}) — ${trace.summary}`;
        return done({ ok: false, fingerprint, cross, reason, trace });
      }
      return done({ ok: true, fingerprint });
    } catch (e) {
      return done({ ok: false, reason: visionErrText(e) });
    }
  }

  trace(kernels: VisionKernelSet = this.set, keep?: (stage: string, name: string) => boolean): Promise<VisionTrace> {
    return this.serial(() => {
      if (this.disposed) throw new Error("vision: tower disposed");
      return this.traceUnlocked(kernels, keep);
    });
  }

  private async traceUnlocked(kernels: VisionKernelSet, keep?: (stage: string, name: string) => boolean): Promise<VisionTrace> {
    // the other set may never have been compiled (compileAll skips what already is)
    await this.g.compileAll(this.names(kernels));
    const { rgb, side } = visionSmokeRgb();
    const prep = visionPrepareImage(rgb, side, side, this.config, this.imageLimits);
    const stages: VisionTraceStage[] = [];
    let first: VisionTrace["firstNonFinite"];
    const tracer: VisionTraceFn = async (stage, buffers) => {
      const st: VisionTraceStage = { stage, buffers: [] };
      for (const b of buffers) {
        const data = await visionReadbackF32(this.g.device, b.buf, b.count * 4);
        let bad = 0, absMax = 0;
        for (let i = 0; i < data.length; i++) {
          const v = data[i];
          if (!Number.isFinite(v)) bad++;
          else if (Math.abs(v) > absMax) absMax = Math.abs(v);
        }
        st.buffers.push({ name: b.name, total: data.length, nonFinite: bad, absMax, ...(keep?.(stage, b.name) ? { data } : {}) });
        if (bad && !first) first = { stage, name: b.name, nonFinite: bad, total: data.length };
      }
      stages.push(st);
    };
    let error: string | undefined;
    try {
      const out = await visionForward(this.g, this.config, this.w8, prep.img, prep.w, prep.h, undefined, kernels, tracer);
      out.destroy();
    } catch (e) {
      error = visionErrText(e);
    }
    const w8 = this.w8;
    const fmt = (x: number): string => x >= 1e6 ? `${(x / 1e6).toFixed(1)}M` : String(x);
    const badStage = first ? stages.find((s) => s.stage === first!.stage) : undefined;
    const cleanBefore = first ? stages.slice(0, stages.indexOf(badStage!)).map((s) => s.stage) : stages.map((s) => s.stage);
    const range = cleanBefore.length === 0 ? "none" : cleanBefore.length === 1 ? cleanBefore[0] : `${cleanBefore[0]} … ${cleanBefore[cleanBefore.length - 1]}`;
    let summary = `trace(${kernels}): weights ${w8.nonFiniteWeights} non-finite of ${fmt(w8.checkedWeights)} checked; finite stages: ${range}`;
    if (badStage) {
      summary += `; first non-finite at ${badStage.stage}: ${badStage.buffers.map((b) => `${b.name} ${b.nonFinite ? `${b.nonFinite}/${b.total} bad` : `ok |max| ${b.absMax.toPrecision(3)}`}`).join(", ")}`;
    } else if (!error) {
      summary += "; every stage finite";
    }
    if (error) summary += `; forward threw: ${error}`;
    return { kernels, weightsNonFinite: w8.nonFiniteWeights, weightsChecked: w8.checkedWeights, stages, ...(first ? { firstNonFinite: first } : {}), ...(error ? { error } : {}), summary };
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    for (const b of this.w8.all) b.destroy();
    this.g.destroyUniforms();
  }
}

/** what the ladder may use on this device: the host's view (limitOverrides lower the limits, disabledFeatures remove
 *  features) where there is one, the device's otherwise; a feature counts only when the device really has it */
export function visionDeviceCaps(gpu: GpuContext): VisionDeviceCaps {
  const o = (gpu as Partial<GpuHost>).deviceInfo?.limits as Partial<Record<string, number>> | undefined;
  const d = gpu.device.limits;
  const has = (f: string): boolean => gpu.device.features.has(f as GPUFeatureName);
  return {
    maxComputeWorkgroupStorageSize: o?.maxComputeWorkgroupStorageSize ?? d.maxComputeWorkgroupStorageSize,
    maxComputeInvocationsPerWorkgroup: o?.maxComputeInvocationsPerWorkgroup ?? d.maxComputeInvocationsPerWorkgroup,
    maxComputeWorkgroupSizeX: o?.maxComputeWorkgroupSizeX ?? d.maxComputeWorkgroupSizeX,
    maxStorageBuffersPerShaderStage: o?.maxStorageBuffersPerShaderStage ?? d.maxStorageBuffersPerShaderStage,
    f16: has("shader-f16") && gpu.features?.f16 !== false,
    subgroups: has("subgroups") && gpu.features?.subgroups !== false,
    subgroupMinSize: gpu.features?.subgroupMinSize ?? null,
    subgroupMaxSize: gpu.features?.subgroupMaxSize ?? null,
    dot4I8Packed: gpu.features?.dot4I8Packed === true,
  };
}

/** one phrase for a diagnostic or the ready message: how the check judged and by how much */
export function visionCheckSummary(c: VisionCheck): string {
  const verdict = c.ok ? "passed" : "FAILED";
  if (c.method === "known") return `${verdict} the known-answer check, deviation ${(c.error ?? NaN).toExponential(1)} of ${c.threshold}`;
  if (c.method === "cross") return `${verdict} the cross-check against the reference kernels, cosine ${(c.cross?.cosine ?? NaN).toFixed(6)}, rel RMS ${(c.cross?.relRms ?? NaN).toExponential(1)}`;
  return `${verdict} the degeneracy check (no stored answer for these weights)`;
}

/**
 * mmproj GgufFile + GpuContext -> a ready tower: config -> kernel set chosen and compiled (validated) -> weights
 * streamed, packed and uploaded -> the 96x96 known-answer check (VisionCheck). Throws with one
 * printable reason; on failure everything created here is destroyed (the GpuContext is the caller's).
 * Kernel set (LoadVisionTowerOptions.kernels): "auto" (default) walks the ladder int8 → tiled3 → tiled2 → tiled1 → tiled0 →
 * legacy — rungs the device cannot run are skipped, a rung that fails to compile or fails the known-answer check
 * drops to the next, and a later forward that throws switches to the reference set; "tiled" walks the tiled rungs
 * only; one named set is forced and fails instead of falling back.
 */
export async function loadVisionTower(gguf: GgufFile, gpu: GpuContext, opts: LoadVisionTowerOptions = {}): Promise<VisionTower> {
  const say = opts.onProgress ?? ((): void => {});
  const diag = opts.onDiagnostic ?? ((): void => {});
  say({ stage: "header", message: "reading the vision (mmproj) header" });
  const cfg = readVisionConfig(gguf);
  // the matrices' packings decide which matmuls a set compiles (and reject an unsupported type before any GPU work)
  const { kinds } = visionWeightKinds(gguf, cfg);
  const g = new VisionGpu(gpu, cfg.headDim);
  await g.measureRoundTrip(); // §2b: a slow-poll browser (Firefox) gets deeper stage pipelining
  const { request, note } = visionParseKernelRequest(opts.kernels);
  if (note) diag({ stage: "build", label: "vision", message: note });
  const caps = visionDeviceCaps(gpu);
  const ladder: VisionLadderStep[] = [];
  const rungs: VisionKernelSet[] = [];
  for (const set of visionLadderFor(request)) {
    const why = visionTierUnsupportedReason(set, caps, cfg)
      ?? (VISION_TIER_PLANS[set as VisionTier]?.mmI8 && !kinds.has("q8_0") ? "no Q8_0 matrices in this mmproj (the int8 rung changes only the Q8_0 matmuls)" : null);
    if (why) ladder.push({ kernels: set, ok: false, stage: "support", reason: why });
    else rungs.push(set);
  }
  if (rungs.length === 0) {
    throw new Error(`vision: the ${request} kernels cannot run on this device (${ladder.map((s) => `${s.kernels}: ${s.reason}`).join("; ")})`);
  }
  if (request === "auto" && ladder.length > 0) diag({ stage: "build", label: "vision", message: `vision: ${rungs[0]} is the best kernel rung this device supports (${ladder.map((s) => `${s.kernels}: ${s.reason}`).join("; ")})` });
  // P9.7: the weights stream in while the kernels compile — neither needs the other, and both keep every error-scope
  // push / pop pair inside one synchronous block, so their scopes never interleave. Awaited after the compiles.
  const weightsLoad = visionLoadWeights(gguf, cfg, g, opts);
  weightsLoad.catch(() => {});
  let w8: VisionGpuWeights | null = null;
  try {
    // compile the best rung that compiles (a WGSL feature the driver rejects drops a rung, like a failed check)
    let set: VisionKernelSet | null = null;
    while (rungs.length > 0) {
      const cand = rungs.shift() as VisionKernelSet;
      const names = visionKernelNamesFor(cand, kinds);
      say({ stage: "compile", done: 0, total: names.length });
      try {
        await g.compileAll(names, (done, total) => say({ stage: "compile", done, total }));
        set = cand;
        break;
      } catch (e) {
        if (g.lostReason || rungs.length === 0) throw e;
        ladder.push({ kernels: cand, ok: false, stage: "compile", reason: visionErrText(e) });
        diag({ stage: "build", label: "vision", message: `vision: the ${cand} kernels did not compile (${visionErrText(e)}); trying ${rungs[0]}` });
      }
    }
    if (!set) throw new Error("vision: no kernel set compiled");
    w8 = await weightsLoad;
    // P2.2: budget by tokens, capped by what the kernel set's buffers may hold on this device (tower.maxImageTokens)
    const requested = Math.max(4, Math.floor(opts.maxImageTokens ?? VISION_DEFAULT_MAX_IMAGE_TOKENS));
    const tower = new VisionTowerImpl(cfg, g, w8, { maxImageEdge: opts.maxImageEdge ?? Infinity, maxImageTokensRequested: requested }, set, rungs, request, ladder, visionWeightsId(gguf), opts.onDiagnostic);
    const faults = opts.guardFaults ?? bonsaiGuardFaultsFromEnv().faults;
    tower.guardFault = faults.some((f) => f.kind === "image-all") ? "image-all" : faults.some((f) => f.kind === "image") ? "image" : null;
    say({ stage: "check", message: "Checking the vision tower" });
    let check = await tower.smokeTest();
    let firstFailure: VisionCheck | null = null;
    for (;;) {
      ladder.push({ kernels: check.kernels, ok: check.ok, stage: "check", ms: check.ms, ...(check.error !== undefined ? { error: check.error } : {}), ...(check.reason ? { reason: check.reason.split(" — ")[0] } : {}) });
      if (check.ok) break;
      firstFailure ??= check;
      if (!(await tower.nextRung(check.reason ?? "the load check failed"))) break;
      check = await tower.smokeTest();
    }
    check.ladder = tower.tier.ladder;
    if (firstFailure && check !== firstFailure) {
      check.fellBack = { from: firstFailure.kernels, reason: firstFailure.reason ?? "unknown" };
      diag({ stage: "build", label: "vision", message: `vision load check: ${firstFailure.kernels} kernels FAILED (${firstFailure.reason ?? "unknown"}); ${check.kernels} kernels ${visionCheckSummary(check)}` });
    }
    if (!check.ok) {
      tower.dispose();
      throw new Error(`vision: the ${check.kernels} kernels failed the load check — ${check.reason ?? "unknown"}`);
    }
    if (tower.maxImageTokens < requested) diag({ stage: "build", label: "vision", message: `vision: image budget reduced from ${requested} to ${tower.maxImageTokens} tokens (a larger image's ${tower.kernels === "legacy" ? "attention score" : "FFN"} buffer exceeds this device's buffer limits)` });
    say({ stage: "ready", message: `vision tower ready: ${cfg.blockCount} blocks, ${tower.kernels} kernels (${visionCheckSummary(check)}), ${w8.format} weights, ${w8.residentBytes.toLocaleString()} bytes resident` });
    return tower;
  } catch (e) {
    // a compile that failed while the weights were still streaming: free them once they have landed
    w8 ??= await weightsLoad.catch(() => null);
    if (w8) for (const b of w8.all) b.destroy();
    g.destroyUniforms();
    throw e;
  }
}
